/* Once the flow is on, toned sections stop setting their own colours and take the page's:
   the wrapper carries `.dark` (or not) for the section in the middle of the window. Custom
   properties set to `inherit` read the wrapper's values. Unlayered and more specific than the
   theme's `.dark`, so it wins over it. */
[data-rho-flow="on"] [data-rho-tone] {
  --background: inherit;
  --foreground: inherit;
  --card: inherit;
  --card-foreground: inherit;
  --popover: inherit;
  --popover-foreground: inherit;
  --primary: inherit;
  --primary-foreground: inherit;
  --secondary: inherit;
  --secondary-foreground: inherit;
  --muted: inherit;
  --muted-foreground: inherit;
  --accent: inherit;
  --accent-foreground: inherit;
  --destructive: inherit;
  --destructive-foreground: inherit;
  --border: inherit;
  --input: inherit;
  --ring: inherit;
  --highlight: inherit;
  --highlight-foreground: inherit;
  --glow: inherit;
}

/* The crossfade: every colour on the page eases over 0.62s, like the original. In the base
   layer, so an element's own transition utilities (hover timings) still win. */
@layer base {
  @media (prefers-reduced-motion: no-preference) {
    [data-rho-flow="on"],
    [data-rho-flow="on"] * {
      transition-property: color, background-color, border-color, fill, stroke;
      transition-duration: 0.62s;
      transition-timing-function: cubic-bezier(0.32, 0, 0.24, 1);
    }
  }
}

import { useEffect, useRef, useState, type ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./rho-tone-flow.css";

export interface RhoToneFlowProps {
  /** the page's sections; those with data-rho-tone take part */
  children: ReactNode;
  /** tone before the first section is measured */
  initialTone?: "dark" | "light";
  className?: string;
}

export function RhoToneFlow({ children, initialTone = "dark", className }: RhoToneFlowProps) {
  const root = useRef<HTMLDivElement>(null);
  const [tone, setTone] = useState(initialTone);
  const [on, setOn] = useState(false);

  useEffect(() => {
    const el = root.current;
    if (!el) return;
    const sections = Array.from(el.querySelectorAll<HTMLElement>("[data-rho-tone]"));
    if (!sections.length) return;
    // A one-pixel line across the middle of the window: the section it crosses sets the tone.
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            const next = (entry.target as HTMLElement).dataset.rhoTone;
            if (next === "dark" || next === "light") setTone(next);
          }
        }
      },
      { rootMargin: "-50% 0px -50% 0px" },
    );
    sections.forEach((s) => observer.observe(s));
    setOn(true);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={root}
      data-rho-flow={on ? "on" : undefined}
      className={cn(on && tone === "dark" && "dark", "bg-background text-foreground", className)}
    >
      {children}
    </div>
  );
}
